import java.util.*;

public class Main {
    static long INF = (long) 1e18;
    static long answer = 0;
    static int[] memo;

    static int compute_moves(long n) {
        if (n == 0) return 0;
        if (n < memo.length && memo[(int) n] != 0) return memo[(int) n];
        long prev_diff = INF;
        long x = 1;
        int count = 0;
        while (Math.abs(x - n) <= prev_diff) {
            prev_diff = Math.abs(x - n);
            x = x * 10 + 1;
            count++;
        }
        x /= 10;
        if (x > n && x / 10 != 0) {
            if (n < memo.length) {
                return memo[(int) n] = (int) Math.min(count + compute_moves(Math.abs(x - n)),
                        count - 1 + compute_moves(Math.abs(x / 10 - n)));
            }
            return (int) Math.min(count + compute_moves(Math.abs(x - n)),
                    count - 1 + compute_moves(Math.abs(x / 10 - n)));
        }
        if (n < memo.length) {
            return memo[(int) n] = count + compute_moves(Math.abs(x - n));
        }
        return (int) (count + compute_moves(Math.abs(x - n)));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        memo = new int[(int) 1e7];
        System.out.println(compute_moves(n));
        sc.close();
    }
}
